export type TemplateCreateRequestButtonsItemOtpType = 'COPY_CODE' | 'ONE_TAP';

/**
 * Type of event that triggers the webhook.
 *
 * **Message lifecycle events:**
 * - `message.queued`: Message created and queued for sending. `data.status` =
 *   `queued`
 * - `message.sent`: Message accepted by the provider. `data.status` = `sent`
 * - `message.delivered`: Message delivered to recipient. `data.status` =
 *   `delivered`
 * - `message.read`: Message was read by the recipient (WhatsApp only).
 *   `data.status` = `read`
 * - `message.failed`: Message failed to send. `data.status` = `failed`
 *
 * **Inbound events:**
 * - `message.inbound`: New message received from a contact. `data.conversationId`,
 *   the inbox thread id (deep-link with
 *   `https://dashboard.zavu.dev/{locale}/inbox?conv={conversationId}`), is sent on
 *   **email** messages only, and is `null` there on the first message of a
 *   brand-new thread. On every other channel it is absent: read it from `GET
 *   /v1/messages/{messageId}`, which always has it, or from `conversation.new` for
 *   a new contact. Reactions are delivered as `message.inbound` with
 *   `messageType='reaction'`. When the contact replied to (quoted) an earlier
 *   message, `data.content` carries the reply context: `replyToMessageId`,
 *   `replyToProviderMessageId`, `replyToFrom`, `replyToText`, and
 *   `replyToMessageType`. `data.providerTimestamp` is the provider's original
 *   receive time in Unix milliseconds (the moment the channel received the message
 *   from the contact — WhatsApp, Telegram, Instagram, Messenger; `null` for SMS
 *   and email). Compare it against the top-level `timestamp` (when Zavu dispatched
 *   the webhook) to detect and ignore delayed deliveries. When the conversation
 *   was opened from a Click-to-WhatsApp ad or post, `data.referral` carries the ad
 *   attribution — including `ctwaClid`, the identifier Meta's Conversions API
 *   needs to credit a conversion back to that ad. WhatsApp only, and only on the
 *   first message of the thread: it is absent from every later message, so persist
 *   it when it arrives.
 * - `message.unsupported`: Received a message type that is not supported
 *
 * **Broadcast events:**
 * - `broadcast.status_changed`: Broadcast status changed (pending_review,
 *   approved, rejected, sending, completed, cancelled)
 *
 * **Other events:**
 * - `conversation.new`: New conversation started with a contact. `data` carries
 *   `conversationId` (the inbox thread id — deep-link with
 *   `https://dashboard.zavu.dev/{locale}/inbox?conv={conversationId}`), the
 *   `phoneNumber` or `email` key, `channel`, `firstMessageId`, `firstMessageText`,
 *   and `profileName`.
 * - `template.status_changed`: WhatsApp template approval status changed. `data`
 *   carries `templateId`, `name`, `previousStatus`, `currentStatus`,
 *   `rejectionReason`, and `category` — the category Meta currently bills the
 *   template under. Meta can recategorize a template (typically `UTILITY` to
 *   `MARKETING`) at approval or long afterwards, which changes what each message
 *   costs; `category` is how that reaches you. A recategorization with no status
 *   change is delivered as this same event, so compare `category` against what you
 *   hold rather than only reacting to `currentStatus`.
 *
 * **Partner events:**
 * - `invitation.status_changed`: A partner invitation's stored status changed: to
 *   `in_progress`, `completed`, `failed`, `cancelled`, or back to `pending` when
 *   it is resent from the dashboard. A change to the same status sends nothing,
 *   and expiry is not a stored change, so no event is sent when an invitation
 *   expires. Delivered to the project webhook (`POST /v1/invitations/webhook`) of
 *   the project that created the invitation; a parent project does not receive its
 *   sub-accounts' events. `data` carries `invitationId`, `clientName`,
 *   `clientEmail`, `connectionType` (`whatsapp_waba` or `messenger`),
 *   `previousStatus`, and `currentStatus`. On `completed` it also carries
 *   `senderId`, `connectedAccount` (`channel`, `id`, `name`) — the WhatsApp
 *   number or Facebook Page that was linked — and, for WhatsApp,
 *   `wabaAccountId`. On `failed` it carries `failureReason`; the invitation link
 *   stays usable, so a client can retry it.
 *
 * **Voice Agent events:**
 * For every voice event, `data` carries `callId`, `direction`, `from`, `to`,
 * `status`, `durationSeconds`, `endReason`, and `transcriptAvailable`. The
 * terminal events (`call.completed`, `call.failed`) additionally carry `cost` —
 * what the call was billed, in USD, combining telephony and the managed voice
 * pipeline — and `currency`. They are dispatched after the call is charged, so
 * `cost` is populated rather than zero; telephony can still be settling on an
 * outbound call, in which case `GET /v1/calls/{callId}` holds the reconciled
 * figure.
 * - `call.initiated`: An outbound call was created and is dialing, or an inbound
 *   call was received. `data.status` = `ringing`
 * - `call.answered`: The call was answered and the voice agent is connected.
 *   `data.status` = `in_progress`
 * - `call.completed`: The call ended after a conversation. `data.status` =
 *   `completed`; `durationSeconds` and `endReason` describe how it ended, and
 *   `transcriptAvailable` indicates whether a transcript can be fetched.
 * - `call.failed`: The call could not be completed (busy, no answer, canceled, or
 *   an error). `data.status` is the terminal status and `endReason` explains the
 *   cause.
 *
 * **Custom domain events:**
 * - `domain.verified`: A custom email domain passed verification (DKIM, and
 *   SPF/DMARC/MAIL FROM if enhanced records are enabled)
 * - `domain.failed`: A custom email domain failed verification or is partially
 *   verified
 */
export type WebhookEvent =
  | 'message.queued'
  | 'message.sent'
  | 'message.delivered'
  | 'message.read'
  | 'message.status'
  | 'message.failed'
  | 'message.inbound'
  | 'message.unsupported'
  | 'broadcast.status_changed'
  | 'conversation.new'
  | 'template.status_changed'
  | 'invitation.status_changed'
  | 'call.initiated'
  | 'call.answered'
  | 'call.completed'
  | 'call.failed'
  | 'domain.verified'
  | 'domain.failed';

/** Webhook payload structure sent to your endpoint. */
export interface WebhookPayload {
  /** Unique event identifier. */
  id: string;
  type: WebhookEvent;
  /** Unix timestamp in milliseconds when the event was created. */
  timestamp: number;
  /** ID of the sender associated with this event. */
  senderId: string;
  /** ID of the project. */
  projectId: string;
  /**
   * Event-specific data. For message events, contains messageId, to, channel,
   * status, errorCode, and errorMessage.
   */
  data: { [key: string]: unknown };
}

/**
 * Data payload for message webhook events (queued, sent, delivered, failed,
 * inbound).
 */
export interface WebhookMessageData {
  /** ID of the message. */
  messageId: string;
  /**
   * Recipient phone number or email. On `message.inbound` this is your own number
   * (the message's destination).
   */
  to: string;
  /**
   * Sender of the message. Present on `message.inbound`: the contact who sent the
   * message.
   */
  from?: string;
  channel: Channel;
  status: MessageStatus;
  /** Type of the message. Present on `message.inbound`. */
  messageType?: MessageType;
  /**
   * ID of the conversation (inbox thread) this message belongs to. Sent on
   * `message.inbound` for **email** messages only; on SMS, WhatsApp, Telegram,
   * Instagram and Messenger it is absent. Use it to deep-link to the dashboard
   * inbox: `https://dashboard.zavu.dev/{locale}/inbox?conv={conversationId}`. On
   * email it is `null` on the first message of a brand-new thread. In every case,
   * fetch it via `GET /v1/messages/{messageId}`, whose `conversationId` is always
   * populated, or take it from the `conversation.new` event for a new contact.
   */
  conversationId?: string | null;
  /**
   * Text body or media caption. Present on `message.inbound` when the message has
   * text.
   */
  text?: string;
  /** Error code if the message failed. */
  errorCode?: string | null;
  /** Error message if the message failed. */
  errorMessage?: string | null;
  /**
   * The provider's original receive time in Unix milliseconds (when the channel
   * received the message from the contact). Present on `message.inbound` for
   * channels that report it (WhatsApp, Telegram, Instagram, Messenger); null for SMS
   * and email.
   */
  providerTimestamp?: number | null;
  /**
   * Click-to-WhatsApp ad attribution. Present on `message.inbound` only when this is
   * the first message of a conversation opened from a Meta ad or post — absent on
   * every later message in that same thread, and on organic conversations. Read
   * `referral.ctwaClid` here to attribute the conversation, and persist it on your
   * side: this webhook is the only delivery. `GET /v1/messages/{messageId}` also
   * returns it, under `content.referral`.
   */
  referral?: AdReferral;
}

/** Webhook configuration for the sender. */
export interface SenderWebhook {
  /** HTTPS URL that will receive webhook events. */
  url: string;
  /** List of events the webhook is subscribed to. */
  events: Array<WebhookEvent>;
  /**
   * Webhook secret for signature verification. Only returned on create or
   * regenerate.
   */
  secret?: string;
  /**
   * Whether the webhook is active.
   *
   * @defaultValue `true`
   */
  active: boolean;
  signatureVersion: WebhookSignatureVersion;
}

export interface Sender {
  id: string;
  name: string;
  /**
   * Phone number in E.164 format. Absent on a sender that has none: an email-only
   * sender, or one created with only `enableSmsOneway`.
   */
  phoneNumber?: string;
  /**
   * Channels this sender can actually send on right now: configured AND activated.
   * Empty means the sender cannot send or receive anything yet: a phoneNumber alone
   * does not enable SMS or voice, and a connected account that is not activated is
   * left out, because every send on it is refused. Check this rather than inferring
   * capability from phoneNumber or emailAddress, and turn a connected channel on
   * with `POST /v1/senders/{senderId}/channels/{channel}/activate`.
   */
  channels?: Array<string>;
  /**
   * Whether this sender is the project's default.
   *
   * @defaultValue `false`
   */
  isDefault?: boolean;
  webhook?: SenderWebhook;
  /** WhatsApp Business Account information. Only present if a WABA is connected. */
  whatsapp?: SenderWhatsapp;
  /** From-address for the email channel, if configured. */
  emailAddress?: string;
  /**
   * Whether inbound email receiving is enabled for this sender.
   *
   * @defaultValue `false`
   */
  emailReceivingEnabled?: boolean;
  /**
   * Whether catch-all receiving is enabled. When true (and emailReceivingEnabled is
   * true), this sender receives email addressed to any local part at its domain, not
   * just its own address. The original recipient is delivered in the message.inbound
   * webhook's data.to.
   *
   * @defaultValue `false`
   */
  emailCatchAllEnabled?: boolean;
  createdAt?: string;
  updatedAt?: string;
}

export interface SenderWhatsapp {
  /** WhatsApp phone number ID from Meta. */
  phoneNumberId?: string;
  /** Display phone number. */
  displayPhoneNumber?: string;
  /** Payment configuration status from Meta. */
  paymentStatus?: SenderWhatsappPaymentStatus;
}

export interface SenderWhatsappPaymentStatus {
  /** Payment setup status (COMPLETE, NOT_STARTED, etc.). */
  setupStatus?: string;
  /** Payment method status (VALID, NONE, etc.). */
  methodStatus?: string;
  /**
   * Whether template messages can be sent. Requires setupStatus=COMPLETE and
   * methodStatus=VALID.
   */
  canSendTemplates?: boolean;
}

/**
 * Create a sender. Provide `phoneNumber` for an SMS/WhatsApp sender,
 * `emailAddress` (with a verified email domain) for an email sender, or
 * `enableSmsOneway: true` for a zero-setup one-way SMS sender — at least one is
 * required.
 */
export interface SenderCreateRequest {
  name: string;
  /**
   * Phone number in E.164 format, and it must be a number your project already owns
   * (see `GET /v1/phone-numbers`). The number is routed to the sender as part of
   * this call, which is what turns the SMS channel on. Passing a number the project
   * does not own, one already attached to another sender, or one rejected in
   * regulatory review returns 400 rather than creating a sender that cannot send. A
   * number still under review is attached and starts carrying messages when it is
   * approved. Omit for an email-only sender.
   */
  phoneNumber?: string;
  /**
   * Let this sender place and answer phone calls. Requires `phoneNumber`; enabling
   * it without one returns 400. Check the `channels` array on the response to
   * confirm `voice` is on.
   *
   * @defaultValue `false`
   */
  enableVoice?: boolean;
  /**
   * Enable the one-way SMS channel (`sms_oneway`). No phone number and no
   * credential, so it is the fastest way to get a sender that can send. Recipients
   * cannot reply. Sending to a US or Canadian (+1) number still needs an approved
   * 10DLC campaign, and is refused with `403 ten_dlc_required` until then. Confirm
   * with `sms_oneway` in the `channels` array on the response.
   *
   * @defaultValue `false`
   */
  enableSmsOneway?: boolean;
  /** @defaultValue `false` */
  setAsDefault?: boolean;
  /** HTTPS URL for webhook events. */
  webhookUrl?: string;
  /** Events to subscribe to. */
  webhookEvents?: Array<WebhookEvent>;
  /**
   * From-address for the email channel (e.g. noreply@yourdomain.com). The address's
   * domain must be a verified email domain in your project. Setting this attaches
   * the email channel to the sender.
   */
  emailAddress?: string;
  /**
   * ID of the verified email domain to attach. Optional — resolved from
   * `emailAddress`'s domain when omitted.
   */
  emailDomainId?: string;
  /** Display name shown in the recipient's inbox for the email channel. */
  emailFromName?: string;
  /**
   * Enable inbound email receiving on this sender. Requires a verified inbound MX
   * record on the domain; the request is ignored otherwise. Read
   * `emailReceivingEnabled` back off the response to see whether it was applied —
   * it comes back `false` when the MX has not verified.
   */
  emailReceivingEnabled?: boolean;
  /**
   * Signature scheme for this sender's webhook. Defaults to `v2`, which is correct
   * for a new receiver. Pass `v1+v2` when this sender points at an endpoint that
   * already serves an older sender still verifying `v1`.
   */
  webhookSignatureVersion?: WebhookSignatureVersion;
}

export interface SenderUpdateRequest {
  name?: string;
  /**
   * Turn the voice channel on or off. The sender must already have a phone number
   * provisioned for calls; enabling it otherwise returns 400 instead of storing a
   * flag that changes nothing. Confirm with the `channels` array on the response.
   */
  enableVoice?: boolean;
  /**
   * Turn the one-way SMS channel on or off. Enabling needs no number or credential
   * and takes effect immediately (US and Canadian destinations still need an
   * approved 10DLC campaign); disabling removes the channel from the sender. Confirm
   * with the `channels` array on the response.
   */
  enableSmsOneway?: boolean;
  setAsDefault?: boolean;
  /** HTTPS URL for webhook events. Set to null to remove webhook. */
  webhookUrl?: string | null;
  /** Events to subscribe to. */
  webhookEvents?: Array<WebhookEvent>;
  /** Whether the webhook is active. */
  webhookActive?: boolean;
  /**
   * Enable or disable inbound email receiving for this sender. Enabling requires a
   * verified inbound MX record on the domain; the request is ignored otherwise, and
   * `emailReceivingEnabled` comes back `false` on the response. Disabling always
   * applies.
   */
  emailReceivingEnabled?: boolean;
  /**
   * Enable or disable domain catch-all. When enabled (with emailReceivingEnabled
   * true), this sender receives email for any address at its domain. Ignored
   * (treated as false) if receiving is not enabled.
   */
  emailCatchAllEnabled?: boolean;
  /**
   * Attach or change the sender's email from-address (e.g. noreply@yourdomain.com).
   * The domain must be a verified email domain in your project.
   */
  emailAddress?: string;
  /**
   * ID of the verified email domain to attach. Optional — resolved from
   * `emailAddress`'s domain when omitted.
   */
  emailDomainId?: string;
  /** Display name shown in the recipient's inbox for the email channel. */
  emailFromName?: string;
  /**
   * Move this webhook between signature schemes. `v1` -> `v2` directly returns
   * `400`; go through `v1+v2` first. See
   * https://docs.zavu.dev/guides/receiving-messages/signature-migration
   */
  webhookSignatureVersion?: WebhookSignatureVersion;
}

export interface WebhookSecretResponse {
  /** The new webhook secret. */
  secret: string;
}

