/** Broadcast delivery channel. Use 'smart' for per-contact intelligent routing. */
export type BroadcastChannel = 'smart' | 'sms' | 'sms_oneway' | 'whatsapp' | 'telegram' | 'email';

/**
 * Current status of the broadcast. `pending_review`: in the automated content
 * review. `pending_admin_review`: the automated review passed and it waits for a
 * person, which is where every channel but a WhatsApp broadcast on an approved
 * template goes. `rejected`: the review refused it; edit it and retry the review,
 * or escalate. `scheduled` and `sending` follow approval.
 */
export type BroadcastStatus =
  | 'draft'
  | 'pending_review'
  | 'pending_admin_review'
  | 'approved'
  | 'rejected'
  | 'escalated'
  | 'rejected_final'
  | 'scheduled'
  | 'sending'
  | 'paused'
  | 'completed'
  | 'cancelled'
  | 'failed';

/**
 * Status of a contact within a broadcast.
 *
 * - `pending`, `queued`, `sending`: not handed to the provider yet.
 * - `sent`: accepted by the provider; delivery is not confirmed yet. Channels that
 *   never report delivery leave the recipient here.
 * - `delivered`: the channel confirmed delivery to the device. A WhatsApp read
 *   receipt also counts as delivered.
 * - `failed`: not delivered. A recipient can move from `sent` or `delivered` to
 *   `failed` when the provider reports a failure late.
 * - `skipped`: not sent, because the recipient opted out of the channel or the
 *   broadcast was cancelled before reaching it.
 */
export type BroadcastContactStatus =
  | 'pending'
  | 'queued'
  | 'sending'
  | 'sent'
  | 'delivered'
  | 'failed'
  | 'skipped';

/** Type of message for broadcast. */
export type BroadcastMessageType = 'text' | 'image' | 'video' | 'audio' | 'document' | 'template';

/** Content for non-text broadcast message types. */
