export interface AgentStats {
  totalInvocations: number;
  totalTokensUsed: number;
  /** Total cost in USD. */
  totalCost: number;
  /**
   * Successful executions among the agent's 100 most recent. Executions with status
   * `filtered` (messages the agent never ran on) are not counted here, in
   * `errorCount` or in `avgLatencyMs`.
   */
  successCount: number;
  /** Failed executions among the agent's 100 most recent. */
  errorCount: number;
  /**
   * Average latency of the agent's 100 most recent executions, `filtered` excluded.
   * Null when there are none.
   */
  avgLatencyMs?: number | null;
}

export interface AgentExecution {
  id: string;
  agentId: string;
  inboundMessageId?: string;
  responseMessageId?: string | null;
  responseText?: string | null;
  status: AgentExecutionStatus;
  errorMessage?: string | null;
  inputTokens: number;
  outputTokens: number;
  latencyMs: number;
  /** Cost in USD. */
  cost: number;
  createdAt: string;
  /**
   * Knowledge-base chunks retrieved for this answer. Zero on an agent that has
   * documents attached means the reply was not grounded in them, which is otherwise
   * indistinguishable from a correct answer in this record. Absent on executions
   * recorded before this field existed, which is not the same as zero.
   */
  knowledgeChunksUsed?: number | null;
  /**
   * Tools the agent called while producing this reply. Zero on an agent that has
   * tools configured means it answered without calling any — the case where a
   * reply says it will look something up and nothing ever reaches your endpoint.
   * Absent on executions recorded before this field existed, which is not the same
   * as zero.
   */
  toolCalls?: number | null;
}

/**
 * What starts a flow.
 *
 * - `keyword`: the message contains one of the words listed in `keywords`. Plain
 *   substring matching, so a word inside another word still counts.
 * - `intent`: the message MEANS what `intent` describes, whatever words it uses.
 * - `always`: any message starts it.
 * - `manual`: reserved. Nothing starts a `manual` flow today — it is accepted
 *   and stored, and no message or endpoint runs it.
 */
export type FlowTriggerType = 'keyword' | 'intent' | 'always' | 'manual';

/** Type of flow step. */
export type FlowStepType = 'message' | 'collect' | 'condition' | 'tool' | 'llm' | 'transfer';

export interface FlowTrigger {
  type: FlowTriggerType;
  /**
   * Words that start the flow, for `keyword` triggers. Matched as substrings,
   * case-insensitively, against the whole message: a flow on `info` also starts on
   * "no quiero info". Use `intent` when that matters.
   */
  keywords?: Array<string>;
  /**
   * One plain sentence describing what the contact wants, for `intent` triggers. Any
   * language.
   *
   * The message is judged for meaning, not for words, so "kiero saber el presio"
   * starts a flow whose intent is "quiere saber precios o cotizar", and "no quiero
   * info de precios" starts nothing.
   *
   * A `keyword` or `always` flow with a higher `priority` is matched first and wins.
   * At most 12 intent flows are considered per message, highest priority first. When
   * the classification is unavailable or uncertain, the message is handled as if no
   * intent matched, so a flow never starts on a guess.
   */
  intent?: string;
}

export interface FlowStep {
  /** Unique step identifier. */
  id: string;
  type: FlowStepType;
  /** Step configuration (varies by type). */
  config: { [key: string]: unknown };
  /** ID of the next step to execute. */
  nextStepId?: string | null;
}

export interface AgentFlow {
  id: string;
  agentId: string;
  name: string;
  description?: string | null;
  trigger: FlowTrigger;
  steps: Array<FlowStep>;
  enabled: boolean;
  /** Priority when multiple flows match (higher = more priority). */
  priority: number;
  createdAt: string;
  updatedAt: string;
}

export interface FlowCreateRequest {
  name: string;
  description?: string;
  trigger: FlowTrigger;
  /**
   * The first step runs on the message that started the flow. It cannot be a
   * `condition` without a `defaultGoto`: nothing has been collected yet, so its
   * conditions evaluate the same way on every message, and the request is refused
   * with `400 invalid_request`.
   *
   * A flow that ends on that first message without replying hands the message to the
   * agent, which answers it. A `transfer` step stays silent.
   */
  steps: Array<FlowStep>;
  /** @defaultValue `false` */
  enabled?: boolean;
  /** @defaultValue `0` */
  priority?: number;
}

export interface FlowUpdateRequest {
  name?: string;
  description?: string;
  trigger?: FlowTrigger;
  /**
   * The first step runs on the message that started the flow. It cannot be a
   * `condition` without a `defaultGoto`: nothing has been collected yet, so its
   * conditions evaluate the same way on every message, and the request is refused
   * with `400 invalid_request`.
   *
   * A flow that ends on that first message without replying hands the message to the
   * agent, which answers it. A `transfer` step stays silent.
   */
  steps?: Array<FlowStep>;
  enabled?: boolean;
  priority?: number;
}

export interface FlowResponse {
  flow: AgentFlow;
}

