/** Lifecycle status of a Zavu Function. */
export type ZavuFunctionStatus = 'draft' | 'bundling' | 'deploying' | 'active' | 'failed' | 'disabled';

/** Runtime the function is deployed on. */
export type ZavuFunctionRuntime = 'nodejs24';

/**
 * A Zavu Function — user-supplied TypeScript that runs in Zavu Cloud and reacts
 * to messaging events or HTTP requests.
 */
export interface ZavuFunction {
  id: string;
  /** URL-safe identifier, unique per project. */
  slug: string;
  name: string;
  description?: string | null;
  runtime: ZavuFunctionRuntime;
  status: ZavuFunctionStatus;
  /** Per-invocation timeout in seconds. */
  timeoutSec: number;
  /** Memory allocation in MB. */
  memoryMb: number;
  /** Whether the function can be invoked over HTTPS via its public URL. */
  httpEnabled: boolean;
  /**
   * HTTPS endpoint, present only while httpEnabled is true. Null otherwise,
   * including for a function that was previously exposed — the stored URL stops
   * serving the moment HTTP is turned off, so it is never returned.
   */
  publicUrl?: string | null;
  /**
   * npm dependencies installed in the function bundle. Keys are package names,
   * values are semver ranges.
   */
  dependencies: { [key: string]: string };
  /** ID of the deployment currently serving traffic. */
  activeDeploymentId?: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ZavuFunctionResponse {
  function: ZavuFunction;
}

export interface FunctionCreateRequest {
  /** URL-safe identifier (lowercase, digits, hyphens). Must be unique per project. */
  slug: string;
  name: string;
  description?: string;
  runtime?: ZavuFunctionRuntime;
  /**
   * Per-invocation timeout in seconds. Event and cron invocations are asynchronous,
   * so a long timeout only bounds cost; a tool called during a live conversation
   * holds up the reply, and a function exposed over HTTP is additionally bounded by
   * the platform's HTTP response limit.
   *
   * @defaultValue `30`
   */
  timeoutSec?: number;
  /** @defaultValue `256` */
  memoryMb?: FunctionCreateRequestMemoryMb;
  /**
   * Whether to expose a public HTTPS URL for this function.
   *
   * @defaultValue `false`
   */
  httpEnabled?: boolean;
  /**
   * The project's source files, keyed by path relative to the project root (e.g.
   * `index.ts`, `lib/orders.ts`). Imports between them are resolved when the
   * function is built, so a function can be split across as many files as it needs.
   *
   * Paths must be relative and use forward slashes; `..`, `node_modules/` and
   * `package.json` are rejected. npm packages are not uploaded here — declare them
   * under `dependencies` and Zavu installs them. Limits: 200 files and 900,000 bytes
   * for the whole tree.
   */
  files?: { [key: string]: string };
  /**
   * Which file in `files` is the entry point. Defaults to `index.ts`.
   *
   * @defaultValue `"index.ts"`
   */
  entrypoint?: string;
  /**
   * Shortcut for a single-file function: exactly equivalent to sending `files` with
   * one entry named after `entrypoint` (`index.ts` by default). Fully supported —
   * use whichever fits. If both are sent, `files` wins.
   */
  sourceCode?: string;
  /** npm dependencies. Keys are package names, values are semver ranges. */
  dependencies?: { [key: string]: string };
}

export type FunctionCreateRequestMemoryMb = 128 | 256 | 512 | 1024;

/**
 * Optional source/dependencies update applied before deploying. Omit every field
 * to redeploy the current draft as-is.
 */
export interface FunctionDeployRequest {
  /**
   * The project's source files, keyed by path relative to the project root (e.g.
   * `index.ts`, `lib/orders.ts`). Imports between them are resolved when the
   * function is built, so a function can be split across as many files as it needs.
   *
   * Paths must be relative and use forward slashes; `..`, `node_modules/` and
   * `package.json` are rejected. npm packages are not uploaded here — declare them
   * under `dependencies` and Zavu installs them. Limits: 200 files and 900,000 bytes
   * for the whole tree.
   */
  files?: { [key: string]: string };
  /**
   * Which file in `files` is the entry point. Defaults to `index.ts`.
   *
   * @defaultValue `"index.ts"`
   */
  entrypoint?: string;
  /**
   * Shortcut for a single-file function: exactly equivalent to sending `files` with
   * one entry named after `entrypoint` (`index.ts` by default). Fully supported —
   * use whichever fits. If both are sent, `files` wins.
   */
  sourceCode?: string;
  /** New dependency map (replaces existing dependencies). */
  dependencies?: { [key: string]: string };
}

/** Stage of a function deployment. */
export type FunctionDeploymentStatus =
  | 'pending'
  | 'bundling'
  | 'uploading'
  | 'publishing'
  | 'active'
  | 'failed'
  | 'superseded';

export interface FunctionDeployment {
  id: string;
  functionId: string;
  /** Monotonically increasing deployment version, starting at 1. */
  version: number;
  status: FunctionDeploymentStatus;
  /** Total size of the deployed source tree in bytes. */
  sourceCodeBytes?: number | null;
  /** Size of the built bundle in bytes. Null until the build finishes. */
  bundleBytes?: number | null;
  /** Failure reason when status is 'failed'. */
  errorMessage?: string | null;
  /**
   * What the build printed: dependency installation, the bundler's output, and the
   * compiler's message when it failed. Returned when fetching a single deployment,
   * omitted from the list. Read this first when a deploy fails — `errorMessage` is
   * often the outer wrapper's summary, and the line that names the broken import or
   * the syntax error is here.
   */
  buildLogs?: string | null;
  deployedAt?: string | null;
  createdAt: string;
}

export interface FunctionDeploymentResponse {
  deployment: FunctionDeployment;
}

export interface FunctionLogEvent {
  timestamp: string;
  message: string;
}

export interface FunctionLogsResponse {
  events: Array<FunctionLogEvent>;
  /** Pass to the next request to fetch the following page of logs. */
  nextToken?: string | null;
}

/**
 * A GitHub repository bound to a function. A push to `branch` deploys the
 * function. A function holds at most one link.
 */
export interface GitRepoLink {
  id: string;
  functionId: string;
  provider: 'github';
  owner: string;
  repo: string;
  /** Only pushes to this branch deploy. */
  branch: string;
  /**
   * Subdirectory holding the project, for monorepos. Null when the project is at the
   * repository root.
   */
  rootDir?: string | null;
  /** When false the link is kept and pushes are ignored. */
  autoDeploy: boolean;
  /**
   * How this link authenticates, decided by the server rather than by the caller.
   * - `app`: the Zavu GitHub App is installed on the account. Pushes arrive on the
   *   app's webhook and private repositories work. Nothing to configure in the
   *   repository.
   * - `manual`: no installation. The link carries its own secret and you add the
   *   webhook to the repository yourself.
   */
  connection: GitRepoLinkConnection;
  lastStatus?: GitRepoLinkLastStatus | null;
  lastCommitSha?: string | null;
  lastCommitMessage?: string | null;
  /** Why the last deploy failed. Null otherwise. */
  lastError?: string | null;
  lastDeployAt?: string | null;
  createdAt: string;
  updatedAt: string;
}

export type GitRepoLinkConnection = 'app' | 'manual';

export type GitRepoLinkLastStatus = 'deploying' | 'deployed' | 'failed';

export interface GitRepoLinkResponse {
  link: GitRepoLink;
  /**
   * Endpoint that receives GitHub's push deliveries. Only needed on a `manual` link,
   * where you add it to the repository yourself.
   */
  webhookUrl: string;
  /**
   * Shared secret for the repository's webhook. **Returned only when creating a
   * `manual` link, and only there** — every later read strips it, and re-linking
   * mints a new one. Absent entirely on an `app` link, which needs no secret of its
   * own.
   */
  webhookSecret?: string;
}

/**
 * Voice Agent configuration on a sender's AI agent. Controls how the agent behaves
 * on inbound and outbound phone calls through Zavu's managed voice pipeline
 * (speech recognition, the agent's LLM, and speech synthesis, with real-time
 * interruption handling).
 */
export interface AgentVoiceConfig {
  /**
   * Whether the agent handles voice calls. When false, the sender's number is not
   * answered by the voice agent and outbound calls are rejected.
   */
  enabled: boolean;
  /**
   * Opening line the agent speaks when the call connects. If omitted, the agent
   * waits for the caller to speak first.
   */
  greeting?: string;
  /**
   * Greeting per language, keyed by language code. Used when the caller's language
   * differs from the one `greeting` is written in.
   */
  greetings?: { [key: string]: string };
  /**
   * BCP-47 language code used for both speech recognition and speech synthesis (e.g.
   * `en`, `es`, `pt-BR`). Auto-detected from the recipient when omitted.
   */
  language?: string;
  /**
   * Model that runs the conversation, co-located in the voice network for lowest
   * latency. Independent of the model used for text messaging. Derived from the
   * agent's text model when omitted.
   */
  model?: string;
  /** Speech-recognition provider. Uses the default when omitted. */
  sttProvider?: string;
  /** Speech-recognition model. Uses the default when omitted. */
  sttModel?: string;
  /** Speech-synthesis provider. Uses the default when omitted. */
  ttsProvider?: string;
  /**
   * Identifier of the synthesized voice that speaks. Choose from the voices
   * available in the dashboard. Uses a neutral default when omitted.
   */
  ttsVoiceId?: string;
  /**
   * Speech rate. 1.0 is natural. Only honoured by voices that support rate control;
   * ignored by the others.
   *
   * @defaultValue `1.0`
   */
  voiceSpeed?: number;
  /**
   * Whether the caller can interrupt the agent while it is speaking (barge-in). When
   * true, the agent stops talking as soon as the caller starts.
   *
   * @defaultValue `true`
   */
  interruptible?: boolean;
  /**
   * Hard limit on call length in minutes. The call ends automatically when reached.
   *
   * @defaultValue `15`
   */
  maxCallDurationMinutes?: number;
  /**
   * How long the agent waits during silence before ending the call.
   *
   * @defaultValue `30`
   */
  maxIdleSeconds?: number;
  /** Whether the call audio is recorded. */
  recordCalls?: boolean;
  /**
   * What the agent does when an answering machine or voicemail is detected on an
   * outbound call.
   *
   * @defaultValue `"hangup"`
   */
  voicemailAction?: AgentVoiceConfigVoicemailAction;
  /**
   * Message spoken when `voicemailAction` is `leave_message`. Falls back to
   * `greeting` when omitted.
   */
  voicemailMessage?: string;
  /**
   * E.164 phone number the agent can transfer the call to. When set, the agent is
   * given a transfer tool it can use to hand the call to a human.
   */
  transferPhoneNumber?: string;
}

export type AgentVoiceConfigVoicemailAction = 'hangup' | 'leave_message';

export interface VoiceCall {
  id: string;
  direction: VoiceCallDirection;
  /**
   * Caller phone number in E.164 format. Your sender's number for outbound calls;
   * the caller's number for inbound calls.
   */
  from: string;
  /** Callee phone number in E.164 format. */
  to: string;
  status: VoiceCallStatus;
  /**
   * Why the call ended (e.g. `agent_ended`, `max_duration`, `transfer`, `hangup`).
   * Present once the call is no longer active.
   */
  endReason?: string | null;
  /** When the call was answered. */
  answeredAt?: string | null;
  /** When the call ended. */
  endedAt?: string | null;
  /** Billable talk time in seconds, measured from answer to hangup. */
  durationSeconds?: number | null;
  /** Number of conversation turns exchanged during the call. */
  turnCount?: number | null;
  /**
   * Ordered transcript of the call. Included when retrieving a single call; omitted
   * from list responses.
   */
  transcript?: Array<VoiceCallTurn>;
  /**
   * Total cost of the call in USD, combining the managed voice pipeline per-minute
   * charge and telephony. Available once the call has ended.
   */
  cost?: number | null;
  /** Arbitrary metadata you attached when creating the call. */
  metadata?: { [key: string]: string };
  createdAt: string;
  updatedAt?: string;
}

/**
 * Request body to place an outbound voice call. The call is answered by the voice
 * agent configured on the sender.
 */
export interface VoiceCallCreateRequest {
  /** Recipient phone number in E.164 format. */
  to: string;
  /**
   * Sender profile that places the call. Uses the project's default sender if
   * omitted. The sender's agent must have voice enabled.
   */
  senderId?: string;
  /** Overrides the agent's configured greeting for this call only. */
  greeting?: string;
  /**
   * Language the agent speaks on this call only, as a BCP-47 tag (`en`, `es`,
   * `es-ES`, `pt-BR`), or `auto` to detect the caller's language and follow it.
   * Overrides the agent's configured language for speech recognition, the agent's
   * replies, and the synthesized voice. If the agent uses a custom voice you
   * supplied, that voice is kept and only the language changes. When omitted, the
   * agent's configured language is used.
   */
  language?: string;
  /** Overrides the agent's maximum call duration for this call only. */
  maxDurationMinutes?: number;
  /**
   * Arbitrary metadata to associate with the call. Returned on the call object and
   * included in voice webhooks.
   */
  metadata?: { [key: string]: string };
}

/**
 * Whether the call was placed by Zavu (outbound) or received from a caller
 * (inbound).
 */
export type VoiceCallDirection = 'inbound' | 'outbound';

export interface VoiceCallResponse {
  call: VoiceCall;
}

/**
 * Lifecycle status of a voice call.
 * - `queued`: outbound call created, not yet dialing.
 * - `ringing`: dialing (outbound) or received and ringing (inbound).
 * - `in_progress`: answered, the agent is connected.
 * - `completed`: ended after a conversation.
 * - `failed`: could not be completed.
 * - `busy`: the line was busy.
 * - `no_answer`: rang but was not answered.
 * - `canceled`: canceled before it was answered.
 */
export type VoiceCallStatus =
  | 'queued'
  | 'ringing'
  | 'in_progress'
  | 'completed'
  | 'failed'
  | 'busy'
  | 'no_answer'
  | 'canceled';

/** A single turn in a voice call transcript. */
export interface VoiceCallTurn {
  /** Ordinal position of the turn within the call, starting at 0. */
  seq: number;
  /**
   * Who produced the turn. `tool` records a tool call the agent made during the
   * conversation.
   */
  role: VoiceCallTurnRole;
  /**
   * Transcribed speech for `user` and `assistant` turns, or a JSON summary of the
   * tool call for `tool` turns.
   */
  text: string;
  /** When the turn started. */
  startedAt?: string | null;
  /** When the turn ended. */
  endedAt?: string | null;
}

export type VoiceCallTurnRole = 'user' | 'assistant' | 'tool';

/**
 * A fully rendered factory agent: the function files to scaffold plus the secrets
 * it needs. Returned by GET /v1/agent-templates/{templateId} and consumed by `npx
 * zavudev agents pull`.
 */
export interface AgentTemplate {
  id: string;
  name: string;
  summary: string;
  category: AgentTemplateCategory;
  voice: boolean;
  defaultSlug: string;
  files: Array<AgentTemplateFile>;
  /** npm dependencies for the scaffolded function. */
  dependencies: { [key: string]: string };
  requiredSecrets: Array<AgentTemplateRequiredSecretsItem>;
}

export type AgentTemplateCategory = 'sales' | 'support' | 'frontDesk' | 'ops';

export interface AgentTemplateRequiredSecretsItem {
  key: string;
  hint: string;
}

export interface AgentTemplateFile {
  path: string;
  /** File contents to write verbatim. */
  content: string;
}

/** Compact catalog entry for a factory agent. */
export interface AgentTemplateSummary {
  id: string;
  name: string;
  summary: string;
  category: AgentTemplateSummaryCategory;
  /** Whether this agent answers phone calls. */
  voice: boolean;
  toolCount: number;
}

export type AgentTemplateSummaryCategory = 'sales' | 'support' | 'frontDesk' | 'ops';

export interface EmailDomain {
  id: string;
  domain: string;
  /** Overall verification status. */
  status: string;
  dkimStatus: string;
  /**
   * DNS records to publish. Present when fetching a single domain or after adding
   * one.
   */
  dnsRecords?: Array<EmailDomainDnsRecord>;
}

export interface EmailDomainDnsRecord {
  /** DNS record type. */
  type: string;
  /** Record host/name to create. */
  name: string;
  /** Record value. */
  value: string;
  /** Priority (MX records only). */
  priority?: number;
  /**
   * What the record is for. `ownership` is a TXT at `_zavu-verification.<domain>`,
   * returned only when another Zavu account also added this domain and neither has
   * verified it: DKIM records are the same for everyone, so the domain verifies only
   * once this account's own token is published.
   */
  purpose: EmailDomainDnsRecordPurpose;
  /**
   * Whether the record is required to verify + send (DKIM) or recommended for
   * deliverability.
   */
  required: boolean;
}

export type EmailDomainDnsRecordPurpose = 'dkim' | 'spf' | 'dmarc' | 'mail_from' | 'ownership';

/**
 * Run the agent and return what it would say. Nothing is delivered to anyone and
 * no execution is recorded.
 *
 * A run is **billed like a live reply**: on an agent with the `zavu` provider it
 * is charged to your balance at the same price per token, and refused with `402
 * insufficient_balance` at a balance of zero. On a bring-your-own-key agent it
 * costs your provider, not Zavu. `cost` on the response is what this run charged.
 */
export interface AgentTestRequest {
  /** What to say to the agent. */
  message: string;
  /**
   * Prior turns, oldest first, to exercise multi-turn behaviour without persisting a
   * thread. Trimmed to the agent's context window.
   */
  history?: Array<AgentTestRequestHistoryItem>;
  /**
   * Set false to skip retrieval and isolate prompt behaviour from the knowledge
   * base.
   *
   * @defaultValue `true`
   */
  useKnowledgeBase?: boolean;
  /**
   * Run the tools the agent calls instead of reporting the choice and stopping.
   *
   * Off by default because a tool handler talks to the outside world: a rehearsal
   * that charges a card is not a rehearsal. Turn it on to exercise the loop that
   * actually matters — the model picks a tool, the handler answers, the model
   * replies with the result — without sending a message to anyone. What ran comes
   * back in `executedToolCalls`.
   *
   * @defaultValue `false`
   */
  executeTools?: boolean;
}

export interface AgentTestRequestHistoryItem {
  role: AgentTestRequestHistoryItemRole;
  content: string;
}

export type AgentTestRequestHistoryItemRole = 'user' | 'assistant';

export interface AgentTestResponse {
  success: boolean;
  /** What the agent would reply. */
  text: string | null;
  error: string | null;
  inputTokens: number;
  outputTokens: number;
  latencyMs: number;
  /**
   * Knowledge-base chunks retrieved for this message. Zero means the answer was not
   * grounded in your documents.
   */
  knowledgeChunksUsed: number;
  /**
   * Tools that actually ran, in order, when the request set `executeTools`. Empty on
   * a normal dry run, where nothing is executed. An entry with `ok: false` means the
   * agent saw an error and answered around it, which is what a customer would have
   * received.
   */
  executedToolCalls?: Array<AgentTestResponseExecutedToolCallsItem>;
  /**
   * Things that are true of this agent but that a dry run cannot prove. Surfaced so
   * a passing dry run is never mistaken for proof that the agent works live.
   *
   * - The agent being disabled.
   * - Enabled tools that were offered to the model but not run: if the agent picks
   *   one, the reply stops at that choice (see `plannedToolCalls`). Pass
   *   `executeTools` to run them.
   * - Tools that ran for real, when `executeTools` was set, and any that failed.
   * - An agent whose sender has none of the channels it triggers on, which answers
   *   every dry run and no real message.
   * - Contact metadata that exists on a real conversation but not here, and memory
   *   tools (`remember`, `recall`, `save_record`), which have no contact to write
   *   about on a test run.
   */
  warnings: Array<string>;
  /**
   * USD charged to your balance for this run. 0 on a bring-your-own-key agent. When
   * the balance covers only part of a run, that part is charged and the next run is
   * refused with `402`.
   */
  cost: number;
  /**
   * Tools the model chose to call, with the arguments it chose, on a run without
   * `executeTools`. Nothing was executed: the reply stops at the choice. Empty when
   * it answered without reaching for a tool, and on a run that executed tools (see
   * `executedToolCalls`).
   */
  plannedToolCalls: Array<AgentTestResponsePlannedToolCallsItem>;
}

export interface AgentTestResponseExecutedToolCallsItem {
  name: string;
  ok: boolean;
  error?: string | null;
}

export interface AgentTestResponsePlannedToolCallsItem {
  name: string;
  /** The arguments as a JSON string. */
  arguments: string;
}

/**
 * Create an agent that exists on its own. Connect senders afterwards; an agent
 * answers on any number of them.
 *
 * **Sub-resources.** An agent's tools, flows and knowledge bases are reachable at
 * `/v1/agents/{agentId}/tools`, `/v1/agents/{agentId}/flows` and
 * `/v1/agents/{agentId}/knowledge-bases`, mirroring the sender-scoped routes
 * documented under `/v1/senders/{senderId}/agent/...` exactly. Use the
 * agent-scoped form while the agent has no sender: the sender-scoped one cannot
 * address it.
 */
export interface AgentCreateStandaloneRequest {
  name: string;
  provider: AgentProvider;
  model: string;
  systemPrompt: string;
  /**
   * API key for the LLM provider. Required unless provider is 'zavu'. Stored
   * encrypted and never returned.
   */
  apiKey?: string;
  /** @defaultValue `10` */
  contextWindowMessages?: number;
  /** @defaultValue `true` */
  includeContactMetadata?: boolean;
  /** @defaultValue `["*"]` */
  triggerOnChannels?: Array<string>;
  /** @defaultValue `["text"]` */
  triggerOnMessageTypes?: Array<string>;
  maxTokens?: number;
  temperature?: number;
  voice?: AgentVoiceConfig;
}

/**
 * Fields to update on an existing function. Provide at least one. `files` /
 * `sourceCode` and `dependencies` edit the draft and take effect on the next
 * deploy; `httpEnabled` applies immediately to the deployed function.
 */
export interface FunctionUpdateRequest {
  /**
   * The project's source files, keyed by path relative to the project root (e.g.
   * `index.ts`, `lib/orders.ts`). Imports between them are resolved when the
   * function is built, so a function can be split across as many files as it needs.
   *
   * Paths must be relative and use forward slashes; `..`, `node_modules/` and
   * `package.json` are rejected. npm packages are not uploaded here — declare them
   * under `dependencies` and Zavu installs them. Limits: 200 files and 900,000 bytes
   * for the whole tree.
   */
  files?: { [key: string]: string };
  /**
   * Which file in `files` is the entry point. Defaults to `index.ts`.
   *
   * @defaultValue `"index.ts"`
   */
  entrypoint?: string;
  /**
   * Shortcut for a single-file function: exactly equivalent to sending `files` with
   * one entry named after `entrypoint` (`index.ts` by default). Fully supported —
   * use whichever fits. If both are sent, `files` wins.
   */
  sourceCode?: string;
  /** New dependency map (replaces existing dependencies). */
  dependencies?: { [key: string]: string };
  /**
   * Expose the function on its public HTTPS URL, or take it down. Applies to the
   * already-deployed function without redeploying; the URL is returned as
   * `publicUrl`.
   */
  httpEnabled?: boolean;
}

/**
 * Which `X-Zavu-Signature` scheme this receiver is sent.
 *
 * - `v1`: `v1=HMAC_SHA256(secret, body)`. The scheme used before this was
 *   configurable. Existing webhooks stay on it until you move them.
 * - `v2`: `v2=HMAC_SHA256(secret, "{t}.{body}")`. The current scheme, and the
 *   default for new senders. It signs the timestamp together with the body.
 * - `v1+v2`: both signatures, sharing one `t`. The migration setting: a receiver
 *   reading either one works, so you can deploy and confirm your new verifier
 *   before switching over.
 *
 * Moving from `v1` straight to `v2` returns `400`. Set `v1+v2` first. See
 * https://docs.zavu.dev/guides/receiving-messages/signature-migration
 */
export type WebhookSignatureVersion = 'v1' | 'v1+v2' | 'v2';

/**
 * The project-level webhook. It receives project events such as
 * `invitation.status_changed` for this project only: a parent project does not
 * receive its sub-accounts' events, so configure one per sub-account with that
 * sub-account's API key.
 */
